using Microsoft.AspNetCore.Mvc; using ProviderMicroService.Domain; [ApiController][Route("api/providers")] public class ProvidersController:ControllerBase{ IProviderRepository repo; public ProvidersController(IProviderRepository r)=>repo=r; [HttpGet] public async Task<IActionResult> List()=>Ok(await repo.ListAsync()); [HttpGet("{id}")] public async Task<IActionResult> Get(int id){var x=await repo.GetAsync(id);return x==null?NotFound():Ok(x);} [HttpPost] public async Task<IActionResult> Create([FromBody]Provider p){var c=await repo.CreateAsync(p);return Ok(c);} [HttpPut("{id}")] public async Task<IActionResult> Update(int id,[FromBody]Provider p){p.Id=id;return Ok(await repo.UpdateAsync(p));} [HttpDelete("{id}")] public async Task<IActionResult> Delete(int id){await repo.DeleteAsync(id);return NoContent();}}